import{_ as E,l as o,o as t,c as i,v as s,p as B,x as n,d as l,i as m,S as d,b as a}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"敲入事件与对冲踩踏","description":"","frontmatter":{"title":"敲入事件与对冲踩踏","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/snowball-knockin-cascade.md","filePath":"quant/snowball-knockin-cascade.md","lastUpdated":1789023840000}'),h={name:"quant/snowball-knockin-cascade.md"};function A(p,e,c,u,D,f){const r=o("Mermaid");return t(),i("div",null,[e[1]||(e[1]=s('<h1 id="敲入事件与对冲踩踏" tabindex="-1">敲入事件与对冲踩踏 <a class="header-anchor" href="#敲入事件与对冲踩踏" aria-label="Permalink to &quot;敲入事件与对冲踩踏&quot;">​</a></h1><div class="epigraph"><p>障碍附近希腊值不再光滑：敲入一旦从或有变成既成，发行人的复制需求会跳一截；若大量合约的敲入水平堆在同一指数点位，跳的方向会叠成对期货的同步冲击。</p><footer>—— 障碍期权数字风险与对冲见 Taleb、Wilmott 等实务叙述；需求与存货外溢见 Ni, Pearson, Poteshman 及做市商 Gamma 文献</footer></div><p><a href="/quant/snowball-pricing">雪球定价</a>给出单张合约的支付与 Delta。市场风险来自许多张合约共用挂钩标的、共用相近的 \\(B_{\\mathrm{in}}\\)。中证 500、中证 1000 上曾出现发行点位接近、敲入比例接近的存量堆积。指数跌向那一簇水平时，发行人的对冲从「越跌越买的支撑」进入「障碍数字风险」，敲入发生后又从敲入期权变成近似远期空头（对发行人）或投资者开始承担现货。买卖方向在短窗口里可能翻转，期货深度有限，于是出现<strong>对冲踩踏</strong>：不是有人约定一起砸盘，而是复制规则在同一点同时改写订单。本篇写敲入前后的希腊值会计与集中度，对象是风险管理，不是如何在敲入前抢跑。境内场外存量受适当性与柜台规则约束；程序化对冲仍受<a href="/quant/cn-program-trading-rules">程序化规定</a>约束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>敲入前，发行人持有向下敲入看跌，Delta \\(\\Delta_{\\mathrm{pre}}\\in(-1,0)\\)，且 \\(|\\Delta|\\) 随 \\(S\\downarrow B_{\\mathrm{in}}\\) 上升。对冲是买入期货。这一段对指数有缓冲：下跌引发买盘。敲入后，若条款使投资者到期支付变为 \\(S_T\\)，发行人相当于对客户做空指数（须支付 \\(S_T\\)），Delta 跳向 \\(-1\\) 附近，对冲仍是多头期货，但数量与敲入前不必连续。更危险的是障碍本身的数字部分：收盘是否 \\(\\le B_{\\mathrm{in}}\\) 是二元事件，其 Delta 在观察日像针。盘中 \\(S\\) 在 \\(B_{\\mathrm{in}}\\) 上下摆，对冲单可以在买与卖之间剧烈切换。问题是估计：（1）单笔合约敲入时 Delta 的跳；（2）存量名义在 \\(B_{\\mathrm{in}}\\) 上的密度；（3）期货流动性能否吸收同步再平衡。缺任何一项，都会把「雪球会托市」或「雪球会砸盘」写成与状态无关的口号。</p><p>Ni、Pearson、Poteshman 对上市期权的教训是：做市商再平衡可以改变标的波动与到期钉住。雪球的障碍不是上市执行价，但会计相同——存货的 Gamma 与数字风险进入期货订单流。差别是场外仓位不透明，密度要用发行与到期的公开信息、券商披露与指数点位去估，误差大。</p><h3 id="敲入不是亏损本身-是状态切换" tabindex="-1">敲入不是亏损本身，是状态切换 <a class="header-anchor" href="#敲入不是亏损本身-是状态切换" aria-label="Permalink to &quot;敲入不是亏损本身，是状态切换&quot;">​</a></h3><p>条款上，敲入当日投资者未必立刻实现亏损；亏损在「已敲入且最终未敲出」时按期末价兑现。对冲却不能等期末。状态从「或有看跌」变成「几乎确定的下跌参与」，希腊值立刻按新支付函数计算。若此后指数反弹并敲出，合约仍可能终止于票息——对冲又要按敲出概率往回调。因此敲入后的路径仍有敲出期权，Delta 不是简单的 \\(-1\\)，而是「已敲入雪球」的 Delta，通常更接近空头远期再叠加剩余敲出。风控若在敲入瞬间把仓位当普通空头期货一次性对满，可能在反弹敲出时反向超调。</p><p><span class="marginnote">观察若以收盘指数为准，盘中击穿再收回不切换状态，但盘中对冲仍会按条件概率交易。收盘附近的订单更密，这是数字风险的时钟，不是「把指数打到障碍以下」的操作建议。故意冲击收盘以触发或避免敲入，落入操纵与异常交易监管。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>风险账按挂钩标的聚合，而不是按产品名。对每个指数、每个交易日，列出未敲出名义、未敲入名义、已敲入名义，以及 \\(B_{\\mathrm{in}}\\)、\\(B_{\\mathrm{out}}\\) 的直方图。把名义映射到发行人总 Delta、总 Gamma：未敲入部分用障碍期权数值希腊值，已敲入部分用相应支付的希腊值。压力测试至少三条路径：缓跌穿过障碍簇、一日跳空越过障碍簇、跌到障碍附近震荡多日。缓跌给出持续买入的托市段；跳空给出无法在连续 Delta 上调整、缺口后一次性补对冲；震荡给出数字风险的来回交易，消耗期货深度并抬高已实现波动。</p><p>对冲执行受期货涨跌停、保证金、<a href="/quant/cn-fee-cancel-ratio">程序化报撤</a>与会员通道约束。假设可以在障碍上无限量市价成交，会低估缺口。应把期货簿的可成交量当成对冲上限，超出部分记为未对冲 Delta，进入资本与止损，而不是记为已经复制成功。</p><h3 id="集中度比单笔票息更重要" tabindex="-1">集中度比单笔票息更重要 <a class="header-anchor" href="#集中度比单笔票息更重要" aria-label="Permalink to &quot;集中度比单笔票息更重要&quot;">​</a></h3><p>单笔 75% 敲入、名义很小，跳的期货张数可忽略。若数百亿名义的 \\(B_{\\mathrm{in}}\\) 落在指数同一 2% 区间，则该区间的 Gamma 密度可以高过上市期权的执行价墙。发行时点集中（同一波营销、同一点位建仓）会制造这堵墙。分散挂钩、错开障碍、错开观察日，是降低踩踏的结构手段；它们改变的是发行簿，不是某一投资者「如何躲过自己的敲入」。内部风险应拒绝使公司簿在单一指数单一障碍上过度堆积，即使单笔销售仍有票息空间。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>踩踏可以拆成三段。第一段，远离障碍：正的缓冲，发行人买跌，与<a href="/quant/ni-option-demand-pressure">需求压力</a>里做市商正 Gamma 类似（此处因发行人多看跌而买现货）。第二段，贴近障碍的观察窗：数字 Delta 使小幅波动对应大额期货，买卖切换快，期货已实现波动上升，可能把更多合约推进敲入。第三段，簇内大量敲入完成：未敲入名义消失，第一段的买盘来源减弱；已敲入名义按新 Delta 可能仍要持有或调整空头对冲，但「越跌越买」的边际支撑下降。若同时有投资者赎回、券商减发新雪球，买盘更少。指数在障碍簇下方的流动性，因此差于障碍簇上方——不是因为条款惩罚下方，而是对冲规则改了供给。</p><p><span class="marginnote">敲出簇同样能制造同步减仓：指数升到一批 \\(B_{\\mathrm{out}}\\)，提前终止使发行人拆掉多头期货，形成上涨时的卖压。踩踏一词常被只用于下跌敲入；对称地，敲出日也是期货的集中再平衡日。风险日历应同时标敲入墙与敲出墙。</span></p><h3 id="与上市期权-gamma、0dte、清算螺旋的差别" tabindex="-1">与上市期权 Gamma、0DTE、清算螺旋的差别 <a class="header-anchor" href="#与上市期权-gamma、0dte、清算螺旋的差别" aria-label="Permalink to &quot;与上市期权 Gamma、0DTE、清算螺旋的差别&quot;">​</a></h3><p>上市期权的 Gamma 墙在执行价上每日可见；雪球墙在场外，透明度低。0DTE 把墙压缩到一天，见<a href="/quant/amaya-0dte-volatility">0DTE 与波动</a>；雪球墙可以在指数上悬挂数月。清算螺旋是保证金触发的被迫卖出，见<a href="/quant/leverage-liquidation">杠杆与强平</a>；雪球踩踏是复制规则触发的再平衡，发行人未必穿仓，但期货市场仍收到订单冲击。三者可叠加：指数快跌时，期货保证金、雪球敲入、期权负 Gamma 同时要交易。风险加总须在同一标的、同一时钟上，而不是分产品各报各的限额。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>场外名义与障碍分布不是交易所公开全市场数据。券商只能看到自己的簿与部分同行传闻；监管统计若未公开，模型应把密度当成区间估计，并在上限情景上留资本。挂钩指数若停用或编制调整，观察以合约指定的继任规则为准。每日敲入与连续敲入的差别，在跳空日最大：跳空越过 \\(B_{\\mathrm{in}}\\) 时，离散合同仍按收盘判定，但中间没有给对冲的连续路径，缺口风险属于跳跃，Delta 对冲不能消去，见<a href="/quant/delta-hedge-freq">对冲频率</a>。</p><p>不要把本篇写成「在敲入墙前布局期货」的交易手册。利用对冲流去冲击收盘、制造触发，属于市场操纵与异常交易讨论范围之外的禁止项。不要向投资者暗示「发行人一定会托市所以不会敲入」——托市是未敲入段的或有结果，且在墙附近会失效。公开规则下，销售须揭示敲入后可能损失全部本金；内部只应用希腊值与集中度管理自身复制风险。</p><p><span class="marginnote">已敲入产品若允许在后续观察日敲出，投资者仍可能拿回本金加票息。把敲入当日当产品死亡，会高估投资者损失、也会误导对冲：剩余敲出权仍有价值，须继续定价。</span></p>',23)),(t(),B(d,null,{default:n(()=>[m(r,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIST%5B%22%E6%9C%AA%E6%95%B2%E5%87%BA%E5%90%8D%E4%B9%89%E6%B2%BF%20Bin%20%E7%9A%84%E5%AF%86%E5%BA%A6%22%5D%20--%3E%20PRE%5B%22%E6%95%B2%E5%85%A5%E5%89%8D%EF%BC%9A%E5%8F%91%E8%A1%8C%E4%BA%BA%E4%B9%B0%E8%B7%8C%E5%AF%B9%E5%86%B2%22%5D%0A%20%20PRE%20--%3E%20NEAR%5B%22%E6%8E%A5%E8%BF%91%E9%9A%9C%E7%A2%8D%EF%BC%9A%E6%95%B0%E5%AD%97%20Delta%EF%BC%8C%E4%B9%B0%E5%8D%96%E5%88%87%E6%8D%A2%22%5D%0A%20%20NEAR%20--%3E%20KI%5B%22%E6%94%B6%E7%9B%98%E5%88%A4%E5%AE%9A%E6%95%B2%E5%85%A5%22%5D%0A%20%20KI%20--%3E%20POST%5B%22%E5%B7%B2%E6%95%B2%E5%85%A5%EF%BC%9A%E6%94%AF%E4%BB%98%E5%87%BD%E6%95%B0%E5%88%87%E6%8D%A2%EF%BC%8C%E6%94%AF%E6%92%91%E5%87%8F%E5%BC%B1%22%5D%0A%20%20POST%20--%3E%20FUT%5B%22%E8%82%A1%E6%8C%87%E6%9C%9F%E8%B4%A7%E5%86%B2%E5%87%BB%22%5D%0A%20%20NEAR%20--%3E%20FUT%0A%20%20KO%5B%22%E6%95%B2%E5%87%BA%E7%B0%87%22%5D%20--%3E%20UNW%5B%22%E6%8B%86%E6%8E%89%E5%AF%B9%E5%86%B2%E5%A4%9A%E5%A4%B4%22%5D%0A%20%20UNW%20--%3E%20FUT%0A%20%20LIQ%5B%22%E6%9C%9F%E8%B4%A7%E6%B7%B1%E5%BA%A6%E4%B8%8E%E6%B6%A8%E8%B7%8C%E5%81%9C%22%5D%20--%3E%20GAP%5B%22%E6%9C%AA%E5%AF%B9%E5%86%B2%E6%AE%8B%E4%BD%99%20Delta%22%5D%0A%20%20FUT%20--%3E%20GAP%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[l("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"敲入把雪球从或有看跌切换到下跌参与，希腊值在观察日不连续。"),a("li",null,"障碍簇上的名义密度决定期货同步冲击的规模；单笔票息不能代表系统风险。"),a("li",null,"未敲入段的买跌支撑在敲入后减弱；敲出簇会在上涨时带来减仓卖压。"),a("li",null,"对冲受期货流动性、停板与程序化规则限制，不能假设障碍上无限成交。"),a("li",null,"管理对象是自身簿的集中度与数字风险，不是利用墙去冲击指数。"),a("li",null,"出处：障碍期权对冲实务；Ni–Pearson–Poteshman 对冲外溢；雪球条款与场外衍生品适当性公开规范。")],-1))])}const b=E(h,[["render",A]]);export{q as __pageData,b as default};
